from typing import Dict, List, Optional, Tuple
from textkit.extract_headings import extract_headings
from textkit.slugify import slugify


def table_of_contents(markdown: str, max_level: int = 3) -> str:
    if not (1 <= max_level <= 6):
        raise ValueError("max_level must be between 1 and 6")

    headings = extract_headings(markdown)
    if not headings:
        return ""

    # 1. Calculate slugs for ALL headings to match renderer numbering
    all_slugs: List[Optional[str]] = []
    slug_counts: Dict[str, int] = {}

    for _, title in headings:
        base = slugify(title)
        if not base:
            all_slugs.append(None)
            continue

        if base not in slug_counts:
            slug_counts[base] = 0
            all_slugs.append(base)
        else:
            slug_counts[base] += 1
            all_slugs.append(f"{base}-{slug_counts[base]}")

    # 2. Filter headings for TOC and find shallowest level
    toc_data: List[Tuple[int, str, str]] = []
    min_level = 7

    for i, (level, title) in enumerate(headings):
        slug = all_slugs[i]
        if level <= max_level and slug is not None:
            toc_data.append((level, title, slug))
            if level < min_level:
                min_level = level

    if not toc_data:
        return ""

    # 3. Build the lines
    lines = []
    for level, title, slug in toc_data:
        indent = " " * (2 * (level - min_level))
        lines.append(f"{indent}- [{title}](#{slug})")

    return "\n".join(lines)
